#!/bin/sh
# CVE-2026-88806: _XkbReadKeyActions must reject a key action range past
# max_key_code instead of writing past server->key_acts.
name=xkb-key-actions tree=$1 work=$2 dir=$3
source_file=src/xkb/XKBGetMap.c
start='static Status\n_XkbReadKeyActions('
end='\n}\n'
# XlibConf.h is generated by configure, which runs later; Debian builds with
# threads, and the control uses no Display fields.
mkdir -p "$work/inc/X11"
printf "#define XTHREADS 1\n#define XUSE_MTSAFE_API 1\n" > "$work/inc/X11/XlibConf.h"
includes="-I$work/inc -I$tree/include -I$tree/include/X11 -I$tree/src -I$tree/src/xkb"
baseline_error='AddressSanitizer: heap-buffer-overflow'
. "$(dirname "$0")/../../../control-run.sh"
